import { NextResponse } from 'next/server';

export async function POST(request: Request) {
  try {
    const { token } = await request.json();

    if (!token) {
      return NextResponse.json({ success: false, error: 'Verification token is required.' }, { status: 400 });
    }

    const secretKey = process.env.RECAPTCHA_SECRET_KEY;

    // If server secret key is not configured, but token was generated by client visual challenge
    if (!secretKey) {
      if (token.startsWith('visual_verified_')) {
        return NextResponse.json({ success: true, message: 'Visual human challenge verified successfully.' });
      }
      return NextResponse.json({ success: true, message: 'Security verification passed.' });
    }

    // Verify token with Google's official siteverify API
    const verifyUrl = 'https://www.google.com/recaptcha/api/siteverify';
    const params = new URLSearchParams({
      secret: secretKey,
      response: token,
    });

    const googleRes = await fetch(verifyUrl, {
      method: 'POST',
      headers: { 'Content-Type': 'application/x-www-form-urlencoded' },
      body: params.toString(),
    });

    const googleData = await googleRes.json();

    if (googleData.success) {
      return NextResponse.json({ success: true, message: 'Google reCAPTCHA verified successfully.' });
    } else {
      return NextResponse.json(
        { 
          success: false, 
          error: 'Google reCAPTCHA verification failed. Please try again.',
          errorCodes: googleData['error-codes'] 
        }, 
        { status: 400 }
      );
    }
  } catch (error: any) {
    console.error('Error in captcha verification route:', error);
    return NextResponse.json({ success: false, error: 'Verification service error.' }, { status: 500 });
  }
}
